{
    $options = $config['options'] ?? [];
    $defaults = method_exists($connector, 'getDefaultOptions')
        ? $connector->getDefaultOptions()
        : $this->defaultPdoOptions;

    $this->connectorOptionOverrides[] = $options;
    $this->defaultPdoOptions = $defaults;

