/**
 * Get the shared manager that owns migrated connection services.
 *
 * @return static
 */
public static function responsibilityDirector()
{
    if (static::$responsibilityDirector instanceof self) {
        return static::$responsibilityDirector;
    }

    try {
        $container = Container::getInstance();

        if ($container && method_exists($container, 'bound') && $container->bound('db')) {
            $resolved = $container->make('db');

            if ($resolved instanceof self) {
                return static::$responsibilityDirector = $resolved;
            }
        }
    } catch (Throwable $e) {
        // Standalone collaborators may resolve a director without a container.
    }

    $container = new Container;

    return static::$responsibilityDirector = new static($container, new ConnectionFactory($container));
